window.PATTERNS=PATTERNS;   // duel (2-blok) shablonlarga murojaat qiladi
try{ window.isPUnlocked=isPUnlocked; }catch(e){}


let completedPatterns=new Set(SAVED_STATE.completedPatterns||[]);
function isPUnlocked(id){return id<=2||completedPatterns.has(id-1)}

function renderPatterns(){
  const sec=screens.patterns;
  // Scroll holatini eslab qolamiz — qayta chizilganda boshiga sakramasin
  let _sc=0;
  try{ const old=sec.querySelector('.sscroll'); if(old) _sc=old.scrollTop; }catch(e){}
  let rows='';
  PATTERNS.forEach(p=>{
    const ul=isPUnlocked(p.id);
    rows+=`<div class="card pat-card ${ul?'unlocked':'locked'}" data-pat="${p.id}">
      <div class="pidx">${ul?p.id:IC.lock}</div>
      <div class="pbody"><h4>${p.title}</h4><p>${p.formula?'Bosib, to\'liq qoidasini ko\'ring':'Tez orada qo\'shiladi'}</p></div>
      <div class="pchev">${IC.chevR}</div>
    </div>`;
  });
  sec.innerHTML=`<div class="shd"><div><h1>Shablonlar</h1><p>Advanced so'z birikmalari</p></div></div><div class="sscroll" style="padding-top:4px">${rows}</div>`;
  sec.querySelectorAll('.pat-card').forEach(c=>c.addEventListener('click',()=>onPatTap(Number(c.dataset.pat))));
  // Scroll'ni qaytaramiz
  if(_sc){ try{ const s=sec.querySelector('.sscroll'); if(s) s.scrollTop=_sc; }catch(e){} }
}
function onPatTap(id){
  if(!isPUnlocked(id)){showToast("Avval oldingi shablonni oching",IC.lock);return}
  const p=PATTERNS[id-1];
  if(!p.formula){showToast(`${id}-shablon tez orada qo'shiladi`,IC.info);return}
  patOpenView(p, id);
}
/* Formuladan struktura diagrammasini quradi: qismlarni "qat'iy" va "bo'sh joy"ga ajratadi */
function patDiagram(formula){
  // formula ichidagi <span class="slot">...</span> larni ajratamiz
  const parts=[];
  const re=/<span class="slot">([^<]*)<\/span>/g;
  let last=0, m;
  while((m=re.exec(formula))!==null){
    const fixed=formula.slice(last, m.index).replace(/<[^>]+>/g,'').replace(/^[\s,]+|[\s,]+$/g,'').trim();
    if(fixed) parts.push({t:'fixed', v:fixed});
    parts.push({t:'slot', v:m[1].replace(/[\[\]]/g,'')});
    last=re.lastIndex;
  }
  const tail=formula.slice(last).replace(/<[^>]+>/g,'').trim().replace(/[.,]$/,'').trim();
  if(tail) parts.push({t:'fixed', v:tail});
  if(parts.length<2 || parts.length>5) return '';   // juda oddiy yoki murakkab bo'lsa diagramma chizmaymiz
  let html='<div class="pv-diagram">';
  parts.forEach((pt,i)=>{
    if(i>0) html+='<div class="pv-dg-arrow">+</div>';
    html+=`<div class="pv-dg-part ${pt.t}"><div class="pv-dg-lbl">${pt.t==='fixed'?'Qat\u2019iy':'Sizning gap'}</div><div class="pv-dg-val">${pt.v}</div></div>`;
  });
  return html+'</div>';
}
function patOpenView(p, id){
  const old=document.getElementById('patView'); if(old) old.remove();
  const tagsH=(p.tags||[]).map(t=>`<span class="pchip ${t.c}">${t.l}</span>`).join('');
  const diagram=patDiagram(p.formula);
  const exH=p.examples.map((e,i)=>`<div class="pv-ex"><div class="pv-ex-n">${i+1}</div><p>${e}</p></div>`).join('');
  const conH=p.contrast?`<div class="pv-sec"><div class="pv-sec-t">${IC.brain||IC.info} Solishtiring</div>
    <div class="pv-contrast">
      <div class="pv-ct-wrong">${p.contrast.w}</div>
      <div class="pv-ct-arrow"><svg viewBox="0 0 24 24"><path d="M12 5v14M6 13l6 6 6-6"/></svg></div>
      <div class="pv-ct-right">${p.contrast.r}</div>
    </div></div>`:'';
  const dialH=p.dialog?`<div class="pv-sec"><div class="pv-sec-t">${IC.spk||IC.info} Suhbat misoli</div>
    <div class="pv-dialog">${p.dialog.map(l=>`<div class="pv-dl ${l.bold?'me':'other'}"><b>${l.s}:</b> ${l.t}</div>`).join('')}</div></div>`:'';
  const whenH=p.when?`<div class="pv-note">${IC.info}<p><b>Qachon:</b> ${p.when}</p></div>`:'';
  const view=document.createElement('div'); view.id='patView';
  view.innerHTML=`
    <div class="pv-head">
      <button class="pv-back" id="pvBack"><svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg></button>
      <h2>${p.title}</h2>
    </div>
    <div class="pv-scroll">
      ${tagsH?`<div class="pv-tags">${tagsH}</div>`:''}
      <div class="pv-formula">${p.formula}</div>
      ${diagram?`<div class="pv-sec"><div class="pv-sec-t">${IC.brain||IC.info} Tuzilishi</div>${diagram}</div>`:''}
      <div class="pv-sec"><div class="pv-sec-t">${IC.info} Ma'nosi</div><p class="pv-meaning">${p.meaning}</p></div>
      ${conH}
      <div class="pv-sec"><div class="pv-sec-t">${IC.book||IC.info} Misollar</div>${exH}</div>
      ${dialH}
      ${whenH}
      ${p.note?`<div class="pv-note">${IC.info}<p><b>Eslatma:</b> ${p.note}</p></div>`:''}
    </div>`;
  document.body.appendChild(view);
  requestAnimationFrame(()=>view.classList.add('on'));
  const close=()=>{ view.classList.remove('on'); setTimeout(()=>view.remove(),320); };
  document.getElementById('pvBack').addEventListener('click',close);
  // Bu shablon "ko'rildi" — keyingisini ochamiz (lekin sahifani qayta chizmaymiz, faqat holatni saqlaymiz)
  if(!completedPatterns.has(id)){ completedPatterns.add(id); try{ saveState(); }catch(e){}
    try{ if(window.__wdDailyProgress) window.__wdDailyProgress('pattern'); }catch(e){}  // kunlik: shablon yakunlandi
    // Orqada renderPatterns'ni chaqiramiz, lekin foydalanuvchi hali detalda — ko'rinmaydi
    try{ renderPatterns(); }catch(e){} }
}
renderPatterns();
